-- Đang kết xuất đổ cấu trúc cho bảng smartclassroom.sensor_data
CREATE TABLE IF NOT EXISTS `sensor_data` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `sensor_id` int(11) NOT NULL,
  `value` double NOT NULL,
  `recorded_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sensor_time` (`sensor_id`,`recorded_at`),
  CONSTRAINT `sensor_data_ibfk_1` FOREIGN KEY (`sensor_id`) REFERENCES `sensors` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=29889 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

